"use strict";

// Load-time code may build a module-scope value; only a function that runs later may not write it.
const squares = [];
(function fill() {
  for (let i = 0; i < 10; i++) {
    squares.push(i * i);
  }
})();

const separators = /[.,]/g;

function words(text) {
  return text.replace(separators, " ").split(" ");
}

module.exports = { square: (n) => squares[n], words };
